/* Kazakh Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aynur": "moonlight — Turkic ay (moon) + Arabic nur (light)", "Nursultan": "radiant sultan — Arabic nur (light) + sultan", "Aigerim": "wonderful moon — Turkic ay (moon) + kerim (wonderful)", "Timur": "iron — Turkic temur", "Gulnara": "pomegranate flower — Persian gul (flower) + nar (pomegranate)", "Serik": "companion — Turkic", "Nazarbayev": "Family name of Nursultan Nazarbayev.", "Tokayev": "Family name of Kassym-Jomart Tokayev, president of Kazakhstan.", "-uly": "The Kazakh patronymic: son of, as in Nursultanuly.", "-kyzy": "The Kazakh patronymic: daughter of, as in Aigerimkyzy."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aynur';
console.log(lookup(q));

